INSERT INTO categories (id, name, slug, description, icon) VALUES
  ('sarapan', 'Sarapan', 'sarapan', 'Menu pagi cepat, praktis, dan berenergi untuk mengawali hari.', 'Coffee'),
  ('makan-siang', 'Makan Siang', 'makan-siang', 'Hidangan lezat, mengenyangkan, dan pas untuk mengisi tenaga tengah hari.', 'Utensils'),
  ('makan-malam', 'Makan Malam', 'makan-malam', 'Menu santap malam yang hangat, nyaman, dan menenangkan.', 'Moon'),
  ('camilan', 'Camilan', 'camilan', 'Camilan gurih dan renyah untuk teman nugas atau bersantai.', 'Cookie'),
  ('minuman', 'Minuman', 'minuman', 'Minuman segar, pelepas dahaga, dan mudah diracik sendiri.', 'GlassWater'),
  ('dessert', 'Dessert', 'dessert', 'Hidangan penutup manis pencuci mulut yang memanjakan lidah.', 'Cake'),
  ('anak-kos', 'Masakan Anak Kos', 'anak-kos', 'Menu super hemat, minim alat, bahan minimarket/warung, dan anti ribet.', 'Home');
INSERT INTO tools (id, name, slug, icon, description) VALUES
  ('rice-cooker', 'Rice Cooker', 'rice-cooker', 'CookingPot', 'Penanak nasi serbaguna yang bisa untuk menumis, mengukus, dan merebus.'),
  ('wajan', 'Wajan / Kuali', 'wajan', 'Flame', 'Wajan cekung standar untuk menumis cepat atau menggoreng dalam minyak banyak.'),
  ('teflon', 'Teflon / Wajan Datar', 'teflon', 'CircleDot', 'Wajan anti lengket untuk telur dadar, roti panggang, dan tumisan minim minyak.'),
  ('panci', 'Panci Rebus', 'panci', 'Soup', 'Panci tinggi untuk merebus sayur, sup, mie, dan kuah-kuahan.'),
  ('kompor', 'Kompor Gas / Listrik', 'kompor', 'FlameKindling', 'Sumber panas utama memasak di dapur atau kosan.'),
  ('blender', 'Blender', 'blender', 'Sparkles', 'Pencampur dan penghalus bumbu atau buah-buahan secara cepat.'),
  ('microwave', 'Microwave', 'microwave', 'Tv', 'Penghangat dan pemanggang makanan instan dengan gelombang mikro.'),
  ('air-fryer', 'Air Fryer', 'air-fryer', 'Wind', 'Penggoreng tanpa minyak untuk makanan renyah dan lebih sehat.'),
  ('kukusan', 'Kukusan / Steamer', 'kukusan', 'CloudFog', 'Pengukus makanan untuk menjaga kelembapan dan nutrisi bahan makanan.');
INSERT INTO substitutions (original_ingredient, substitute_ingredient, reason, taste_change, texture_change, suitable_for) VALUES
  ('Santan', 'Susu Evaporasi atau Susu UHT + Sedikit Air', 'Menghasilkan tekstur kuah gurih dan creamy tanpa risiko santan pecah.', 'Rasa sedikit lebih manis dan creamy, namun aroma khas kelapa berkurang.', 'Kuah lebih ringan dan tidak terlalu kental berlemak.', 'Sup, soto, gulai ringan, dan minuman.'),
  ('Minyak Goreng', 'Margarin atau Mentega Cair', 'Bisa digunakan untuk menumis bahan dan menambah aroma harum gurih.', 'Aroma tumisan jadi lebih wangi gurih gurih mentega.', 'Tidak ada perbedaan tekstur signifikan pada hasil tumisan.', 'Tumisan, telur dadar, nasi goreng.'),
  ('Kecap Manis', 'Kecap Asin + Gula Merah / Gula Pasir Larut', 'Memberikan perpaduan rasa asin kedelai dan manis karamel yang serupa.', 'Rasa manis sedikit lebih tajam dan kurang beraroma rempah kecap manis asli.', 'Lebih cair dibandingkan kecap manis kental botolan.', 'Nasi goreng, tempe orek, ayam kecap.'),
  ('Tepung Maizena', 'Tepung Tapioka atau Tepung Terigu yang Dilarutkan', 'Sebagai agen pengental kuah capcay atau saus.', 'Rasa netral hampir sama, tepung terigu sedikit lebih keruh warnanya.', 'Tapioka lebih kenyal dan glossy, terigu lebih pekat padat.', 'Capcay, saus kental, sup kental.'),
  ('Saus Tiram', 'Kecap Asin + Sejumput Gula + Kaldu Bubuk Jamur', 'Meniru sensasi umami dan asin gurih khas saus tiram untuk tumisan.', 'Kurang aroma khas tiram/seafood, tapi tetap gurih pekat.', 'Sedikit lebih cair dibanding saus tiram botolan.', 'Tumis kangkung, capcay, nasi goreng.'),
  ('Bawang Bombay', 'Bawang Merah Tambahan (2-3 siung)', 'Keluarga allium yang memberikan aroma harum saat ditumis.', 'Rasa manis karamel bombay berkurang, aroma bawang merah lebih tajam khas nusantara.', 'Irisan lebih kecil dan gampang layu dibanding bombay.', 'Semua tumisan, nasi goreng, sup.'),
  ('Daging Ayam', 'Tahu Putih / Jamur Tiram Suwir', 'Sumber protein nabati ramah kantong kos-kosan dengan daya serap bumbu luar biasa.', 'Rasa lebih ringan dan segar, menyerap bumbu marinasi dengan sangat baik.', 'Tekstur lembut atau kenyal mirip serat daging ayam suwir.', 'Nasi goreng, mie nyemek, sup, tumisan.'),
  ('Telur Ayam', 'Tahu Sutra Hancur (Scrambled Tofu)', 'Alternatif protein nabati yang bisa dibumbui mirip tekstur orak-arik telur.', 'Rasa lebih tawar, perlu tambahan kunyit bubuk dan kaldu bubuk untuk warna dan rasa.', 'Lembut dan basah menyerupai orak-arik telur setengah matang.', 'Nasi goreng, tumisan sayur.'),
  ('Cabai Rawit Merah', 'Bubuk Cabai Kering atau Saus Sambal Botolan', 'Memberikan sensasi pedas instan ketika cabai segar di kulkas habis.', 'Sensasi pedas tetap ada, namun minus aroma segar cabai petik.', 'Tidak ada gigitan renyah potongan cabai segar.', 'Seblak, mie nyemek, sambal kecap.'),
  ('Keju Cheddar', 'Susu Bubuk Gurih atau Saus Mayones Gurih', 'Memberikan sentuhan rasa creamy gurih pada makanan panggangan.', 'Gurih creamy tetap terasa nikmat walau tanpa lelehan khas keju padat.', 'Tidak ada sensasi elastis / parutan keju renyah.', 'Roti bakar, makaroni telur, pancake.');
